// Some portions generated by Claude
import { useEffect, useState } from "react";
import { parseLanguagePreferences } from "./rdf-vocabulary.ts";
import { isSafeSparqlIri, resourceNodeId } from "./rdf-terms.ts";
import { Icon } from "./icons.tsx";
export function LabelPreferences({
  languages,
  onLanguages,
  scope,
  onScope,
  onRefresh,
  onProperty,
}: {
  languages: string[];
  onLanguages: (languages: string[]) => void;
  scope: string;
  onScope: (scope: string) => void;
  onRefresh: () => void;
  onProperty: (property: string) => void;
}) {
  const [language, setLanguage] = useState(""),
    [graph, setGraph] = useState(""),
    [property, setProperty] = useState(""),
    [error, setError] = useState(""),
    [named, setNamed] = useState(scope !== "default" && scope !== "all");
  // The scope can change from outside (a stored graph brings its own back); the panel follows it.
  useEffect(() => {
    const isNamed = scope !== "default" && scope !== "all";
    setNamed(isNamed);
    if (isNamed) setGraph(scope);
  }, [scope]);
  const update = (action: () => void) => {
    try {
      action();
      setError("");
    } catch (e) {
      setError((e as Error).message);
    }
  };
  const move = (index: number, direction: number) => {
    const next = [...languages];
    [next[index], next[index + direction]] = [
      next[index + direction],
      next[index],
    ];
    onLanguages(next);
  };
  return (
    <details className="label-preferences">
      <summary>
        <span>Language and data preferences</span>
        <Icon name="chevron" className="workbench-disclosure-chevron" />
      </summary>
      <p>
        Labels use the first available language in this order. These preferences
        apply to every repository.
      </p>
      <ol>
        {languages.map((tag, index) => (
          <li key={tag}>
            <span>
              {tag === "und" ? "Untagged" : tag === "*" ? "Any language" : tag}
            </span>
            <button
              className="workbench-action workbench-action--ghost workbench-action--icon"
              type="button"
              title={`Move ${tag} earlier`}
              aria-label={`Move ${tag} earlier`}
              disabled={index === 0}
              onClick={() => move(index, -1)}
            >
              ↑
            </button>
            <button
              className="workbench-action workbench-action--ghost workbench-action--icon"
              type="button"
              title={`Move ${tag} later`}
              aria-label={`Move ${tag} later`}
              disabled={index === languages.length - 1}
              onClick={() => move(index, 1)}
            >
              ↓
            </button>
            <button
              className="workbench-action workbench-action--ghost workbench-action--icon"
              type="button"
              title={`Remove ${tag}`}
              aria-label={`Remove ${tag}`}
              disabled={languages.length === 1}
              onClick={() => onLanguages(languages.filter((l) => l !== tag))}
            >
              <Icon name="close" />
            </button>
          </li>
        ))}
      </ol>
      <div className="preference-input-row">
        <input
          aria-label="Language to add"
          placeholder="nb, en, de…"
          value={language}
          onChange={(e) => setLanguage(e.target.value)}
        />
        <button
          className="workbench-action workbench-action--secondary"
          type="button"
          disabled={languages.length >= 16 || !language.trim()}
          onClick={() =>
            update(() => {
              onLanguages(
                parseLanguagePreferences([
                  ...languages,
                  ...language.split(/[,\s]+/),
                ]),
              );
              setLanguage("");
            })
          }
        >
          Add language
        </button>
      </div>
      <small>
        {languages.length}/16 · Regional variants, then untagged labels, then
        another available language are fallbacks.
      </small>
      <label>
        Graph scope for exploration
        <select
          aria-label="Graph scope"
          value={named ? "named" : scope}
          onChange={(e) => {
            setNamed(e.target.value === "named");
            if (e.target.value !== "named") onScope(e.target.value);
            else setGraph(scope === "default" || scope === "all" ? "" : scope);
          }}
        >
          <option value="default">Endpoint default graph</option>
          <option value="all">Default and all named graphs</option>
          <option value="named">A named graph…</option>
        </select>
      </label>
      {named && (
        <div className="preference-input-row">
          <input
            aria-label="Named graph IRI"
            placeholder="Named graph IRI or <_:id>"
            value={graph}
            onChange={(e) => setGraph(e.target.value)}
          />
          <button
            className="workbench-action workbench-action--secondary"
            type="button"
            disabled={!graph.trim()}
            onClick={() =>
              update(() => {
                const resource = resourceNodeId(graph.trim());
                if (!resource) throw new Error("Enter a valid named graph IRI or fixed blank-node reference.");
                onScope(resource);
              })
            }
          >
            Use graph
          </button>
        </div>
      )}
      <label>Additional label property</label>
      <div className="preference-input-row">
        <input
          aria-label="Additional label property IRI"
          placeholder="https://example.org/displayName"
          value={property}
          onChange={(e) => setProperty(e.target.value)}
        />
        <button
          className="workbench-action workbench-action--secondary"
          type="button"
          disabled={!property.trim()}
          onClick={() =>
            update(() => {
              if (!isSafeSparqlIri(property.trim()))
                throw new Error("Enter the full label property IRI.");
              onProperty(property.trim());
              setProperty("");
            })
          }
        >
          Use label
        </button>
      </div>
      <button className="workbench-action workbench-action--secondary" type="button" onClick={onRefresh}>
        Clear cache and refresh labels
      </button>
      {error && <p className="preference-error" role="alert">{error}</p>}
    </details>
  );
}
